      },
      "Message": {
        "User": {
          "userId": "eid_a253c65a",
          "timestamp": "2026-07-05T09:50:00",
          "text": "No problem, team! Let's keep the conversation going and continue to learn from our competitors.",
          "utterranceID": "20260922-13-021bd"
        },
        "Reactions": []
      },
      "ThreadReplies": [],
